class _Integrations:
    """``integrations`` commands."""

    def __init__(self, t: _Transport) -> None:
        self._t = t
        self.setup = _IntegrationsSetup(self._t)

    def list(self, *, available: bool = False, usage: bool = False) -> Any:
        """List your integrations.

        CLI: ``integrations list [--json [--usage]] | integrations list --available [--json]``

        Tag-scoped API keys may run this command.

        Args:
            available: list available integrations
            usage: include per-VM usage (lastUsedAt, usedByVMs); JSON only
        """
        return self._t.call(
            "integrations list",
            [],
            [
                ("available", "bool", available or None),
                ("usage", "bool", usage or None),
            ],
        )

    def add(
        self,
        type: str,
        *,
        act_as_user: bool = False,
        attach: Sequence[str] | None = None,
        bearer: str | None = None,
        comment: str | None = None,
        default: bool = False,
        fields: str | None = None,
        for_: str | None = None,
        headers: Sequence[str] | None = None,
        host_keys: Sequence[str] | None = None,
        name: str | None = None,
        no_auth: bool = False,
        peer: bool = False,
        readonly: bool = False,
        repository: str | None = None,
        strip_prefix: str | None = None,
        target: str | None = None,
        team: bool = False,
    ) -> Any:
        """Add a new integration.



        CLI: ``integrations add <type> [--default | --name=<name> [--team] [args...]]``

        Args:
            act_as_user: authenticate as your GitHub user instead of the exe.dev app
                (github only); pushes and API calls are attributed to your GitHub
                account
            attach: attach to a spec (vm:<name>, tag:<name>, or auto:all)
            bearer: bearer token (shorthand for ``headers=["Authorization:Bearer
                TOKEN"]``; combines with ``headers``)
            comment: optional free-form comment stored with the integration
            default: install the canonical reflection integration with all fields;
                attaches to auto:all unless ``attach=["vm:<name>"]`` is supplied; no
                other customization
            fields: comma-separated reflection fields to expose (email, integrations,
                tags, comment, default_port); 'all' exposes every field including ones
                added in the future; 'none' disables every field (server default: all)
            for_: time-box every ``attach`` to a duration from now (e.g. 2h, 45m);
                access lapses automatically
            headers: header to inject (e.g. X-Auth:secret)
            host_keys: host keys for ssh-key: authorized_keys or known_hosts lines
                (hostnames are ignored), or '*' for any
            name: integration name (required unless ``default=True``)
            no_auth: create an endpoint integration with no injected authentication
            peer: authenticate with a generated API key scoped to the target VM;
                combines with ``headers``/``bearer``
            readonly: restrict the integration to read access (github only); git push
                and write API calls are rejected
            repository: GitHub repository in owner/repo format (required for github)
            strip_prefix: path prefix to strip from each request before forwarding
                (http-proxy only; e.g. /api/v3 makes /api/v3/users reach the target as
                /users)
            target: target URL (required for http-proxy)
            team: create as a team integration
        """
        return self._t.call(
            "integrations add",
            [type],
            [
                ("act-as-user", "bool", act_as_user or None),
                ("attach", "repeated", attach),
                ("bearer", "string", bearer),
                ("comment", "string", comment),
                ("default", "bool", default or None),
                ("fields", "string", fields),
                ("for", "string", for_),
                ("header", "repeated", headers),
                ("host-key", "repeated", host_keys),
                ("name", "string", name),
                ("no-auth", "bool", no_auth or None),
                ("peer", "bool", peer or None),
                ("readonly", "bool", readonly or None),
                ("repository", "string", repository),
                ("strip-prefix", "string", strip_prefix),
                ("target", "string", target),
                ("team", "bool", team or None),
            ],
        )

    def remove(self, name: str, *, team: bool = False) -> Any:
        """Remove an integration.

        CLI: ``integrations remove <name> [--team]``

        Args:
            team: operate on a team integration
        """
        return self._t.call("integrations remove", [name], [("team", "bool", team or None)])

    def test(self, name: str, *, team: bool = False) -> Any:
        """Test an integration's credential (connection check).

        CLI: ``integrations test <name> [--team]``

        Args:
            team: operate on a team integration
        """
        return self._t.call("integrations test", [name], [("team", "bool", team or None)])

    def edit(
        self,
        name: str,
        *args: str,
        act_as_user: bool = False,
        bearer: str | None = None,
        clear_header: bool = False,
        comment: str | None = None,
        fields: str | None = None,
        headers: Sequence[str] | None = None,
        host_keys: Sequence[str] | None = None,
        no_auth: bool = False,
        readonly: bool = False,
        repository: str | None = None,
        strip_prefix: str | None = None,
        target: str | None = None,
        team: bool = False,
        webhook_url: str | None = None,
    ) -> Any:
        """Edit an integration.



        CLI: ``integrations edit <name> [--team] [args...]``

        Args:
            act_as_user: authenticate as your GitHub user instead of the exe.dev app
                (github only)
            bearer: bearer token (shorthand for ``headers=["Authorization:Bearer
                TOKEN"]``; combines with ``headers``)
            clear_header: remove injected headers for http-proxy
            comment: free-form comment stored with the integration
            fields: comma-separated reflection fields to expose (email, integrations,
                tags, comment, default_port); 'all' exposes every field including ones
                added in the future; 'none' disables every field
            headers: header to inject for http-proxy; replaces all existing headers
            host_keys: replacement host keys for ssh-key; replaces the whole list; one -
                reads them piped in
            no_auth: remove injected authentication for http-proxy
            readonly: restrict the integration to read access (github only)
            repository: GitHub repository in owner/repo format
            strip_prefix: path prefix to strip from each request before forwarding
                (http-proxy only; e.g. /api/v3; empty clears it)
            target: target URL for http-proxy
            team: edit a team integration
            webhook_url: replacement Slack or Discord webhook URL
        """
        return self._t.call(
            "integrations edit",
            [name, args],
            [
                ("act-as-user", "bool", act_as_user or None),
                ("bearer", "string", bearer),
                ("clear-header", "bool", clear_header or None),
                ("comment", "string", comment),
                ("fields", "string", fields),
                ("header", "repeated", headers),
                ("host-key", "repeated", host_keys),
                ("no-auth", "bool", no_auth or None),
                ("readonly", "bool", readonly or None),
                ("repository", "string", repository),
                ("strip-prefix", "string", strip_prefix),
                ("target", "string", target),
                ("team", "bool", team or None),
                ("webhook-url", "string", webhook_url),
            ],
        )

    def attach(
        self,
        name: str,
        spec: str,
        *,
        for_: str | None = None,
        team: bool = False,
        until: str | None = None,
    ) -> Any:
        """Attach an integration to a VM, tag, or all VMs.

        A <spec> controls where the integration is mounted:
          vm:<vm-name>   attach to a specific VM (personal only)
          tag:<tag-name> attach to every VM with the given tag
          auto:all       attach to all current and future VMs (personal only)

        You can attach the same integration multiple times with different specs.
        Team integrations only support tag:<tag-name>.

        A grant can be time-boxed with ``for_=<duration>`` or ``until=<RFC3339>``;
        when it lapses, access stops immediately, with nothing to revoke.
        Re-attaching the same spec with a new ``for_``/``until`` extends or shortens it.

        CLI: ``integrations attach <name> <spec> [--team] [--for <duration> | --until <time>]``

        Args:
            for_: time-box the attachment to a duration from now (e.g. 2h, 45m); access
                lapses automatically
            team: operate on a team integration
            until: time-box the attachment until an RFC3339 instant (e.g.
                2026-08-03T20:00:00Z)
        """
        return self._t.call(
            "integrations attach",
            [name, spec],
            [
                ("for", "string", for_),
                ("team", "bool", team or None),
                ("until", "string", until),
            ],
        )

    def detach(self, name: str, spec: str, *, team: bool = False) -> Any:
        """Detach an integration from a VM, tag, or all VMs.

        CLI: ``integrations detach <name> <spec> [--team]``

        Args:
            team: operate on a team integration
        """
        return self._t.call("integrations detach", [name, spec], [("team", "bool", team or None)])

    def rename(self, name: str, new_name: str, *, team: bool = False) -> Any:
        """Rename an integration.

        CLI: ``integrations rename <name> <new-name> [--team]``

        Args:
            team: operate on a team integration
        """
        return self._t.call(
            "integrations rename",
            [name, new_name],
            [("team", "bool", team or None)],
        )

    def catalog(self, query: str | None = None) -> Any:
        """Browse the catalog of ready-made service integrations.

        CLI: ``integrations catalog [service-or-search-term]``
        """
        return self._t.call("integrations catalog", [query])


