    def statement(self, *, from_: str | None = None, to: str | None = None) -> Any:
        """Open a consolidated credit purchase statement.

        CLI: ``billing statement [--from=<YYYY-MM-DD>] [--to=<YYYY-MM-DD>]``

        Args:
            from_: start of the period, YYYY-MM-DD
            to: end of the period, YYYY-MM-DD
        """
        return self._t.call(
            "billing statement",
            [],
            [("from", "string", from_), ("to", "string", to)],
        )


