class _VMDomain:
    """The VM's ``domain`` commands."""

    def __init__(self, vm: VM) -> None:
        self._vm = vm

    def add(self, domain: str, *, wildcard: bool = False) -> t.DomainAddResponse:
        """Link a custom domain to a VM.

        CLI: ``domain add [--wildcard] <vm> <domain>``

        Args:
            wildcard: issue a wildcard (*.<parent>) certificate via DNS-01 delegation
        """
        result: t.DomainAddResponse = self._vm._t.call(
            "domain add",
            [self._vm.name, domain],
            [("wildcard", "bool", wildcard or None)],
            json=True,
        )
        return result

    def remove(self, domain: str) -> t.DomainRmResponse:
        """Remove a custom domain from a VM.

        CLI: ``domain rm <vm> <domain>``
        """
        result: t.DomainRmResponse = self._vm._t.call("domain rm", [self._vm.name, domain], json=True)
        return result


class _VMShare:
    """The VM's ``share`` commands."""

    def __init__(self, vm: VM) -> None:
        self._vm = vm

    def show(self, *, qr: bool = False) -> t.ShareShowResponse:
        """Show current shares for a VM.

        CLI: ``share show <vm>``

        Tag-scoped API keys may run this command.

        Args:
            qr: show QR code for the URL
        """
        result: t.ShareShowResponse = self._vm._t.call("share show", [self._vm.name], [("qr", "bool", qr or None)], json=True)
        return result

    def port(self, port: int | str | None = None) -> t.SharePortResponse:
        """Set the HTTP proxy port for a VM.

        CLI: ``share port <vm> [port]``

        Tag-scoped API keys may run this command.
        """
        result: t.SharePortResponse = self._vm._t.call("share port", [self._vm.name, port], json=True)
        return result

    def set_public(self) -> t.ShareRouteUpdate:
        """Make the HTTP proxy publicly accessible.

        CLI: ``share set-public <vm>``

        Tag-scoped API keys may run this command.
        """
        result: t.ShareRouteUpdate = self._vm._t.call("share set-public", [self._vm.name], json=True)
        return result

    def set_private(self) -> t.ShareRouteUpdate:
        """Restrict the HTTP proxy to authenticated users.

        CLI: ``share set-private <vm>``

        Tag-scoped API keys may run this command.
        """
        result: t.ShareRouteUpdate = self._vm._t.call("share set-private", [self._vm.name], json=True)
        return result

    def add(
        self,
        email: str,
        *,
        message: str | None = None,
        qr: bool = False,
        root: bool = False,
    ) -> t.ShareAddResponse:
        """Share VM with a user via email, or grant shell access with ``root=True``.

        CLI: ``share add <vm> <email|team> [--root] [--message='...']``

        Tag-scoped API keys may run this command.

        Args:
            message: message to include in share invitation
            qr: show QR code for the URL
            root: grant/revoke shell (SSH, Terminal, Shelley) access instead of web-only
        """
        result: t.ShareAddResponse = self._vm._t.call(
            "share add",
            [self._vm.name, email],
            [
                ("message", "string", message),
                ("qr", "bool", qr or None),
                ("root", "bool", root or None),
            ],
            json=True,
        )
        return result

    def remove(self, email: str, *, root: bool = False) -> t.ShareRemoveResponse:
        """Revoke a user's access to a VM, or downgrade shell access to web with ``root=True``.

        CLI: ``share remove <vm> <email|team> [--root]``

        Tag-scoped API keys may run this command.

        Args:
            root: grant/revoke shell (SSH, Terminal, Shelley) access instead of web-only
        """
        result: t.ShareRemoveResponse = self._vm._t.call(
            "share remove",
            [self._vm.name, email],
            [("root", "bool", root or None)],
            json=True,
        )
        return result

    def add_link(self, *, qr: bool = False) -> t.ShareLinkCreated:
        """Create a shareable link for a VM.

        CLI: ``share add-link <vm>``

        Tag-scoped API keys may run this command.

        Args:
            qr: show QR code for the URL
        """
        result: t.ShareLinkCreated = self._vm._t.call(
            "share add-link",
            [self._vm.name],
            [("qr", "bool", qr or None)],
            json=True,
        )
        return result

    def remove_link(self, token: str) -> t.ShareMessage:
        """Revoke a shareable link.

        CLI: ``share remove-link <vm> <token>``

        Tag-scoped API keys may run this command.
        """
        result: t.ShareMessage = self._vm._t.call("share remove-link", [self._vm.name, token], json=True)
        return result

    def receive_email(
        self,
        enabled: bool | None = None,
        *,
        reply_policy: str | None = None,
    ) -> t.ShareReceiveEmailResponse:
        """Enable or disable inbound email for a VM.

        CLI: ``share receive-email <vm> [on|off] [--reply-policy=all|known|owner|none]``

        Tag-scoped API keys may run this command.

        Args:
            reply_policy: restrict who the VM may email: all|known|owner|none
        """
        result: t.ShareReceiveEmailResponse = self._vm._t.call(
            "share receive-email",
            [self._vm.name, on_off(enabled)],
            [("reply-policy", "string", reply_policy)],
            json=True,
        )
        return result


